const answers = ["yes", "no", "yes", "yes", "no"];

let yesCount = 0;
for (const answer of answers) {
  if (answer === "yes") {
    yesCount++;
  }
}
console.log(`Yes answers: ${yesCount}`);

for (const [i, answer] of answers.entries()) {
  console.log(`Answer ${i + 1}: ${answer}`);
}

steps.body:
Most array work is one loop that updates a few variables declared before it.

- **Sum:** start at `0` and add each item. The average is `sum / arr.length`, formatted with `toFixed(n)`.
- **Maximum:** start at `-Infinity` so any real number beats it. **Minimum:** start at `Infinity`.
- **Count:** start at `0` and add 1 when an item matches a condition.
- **Collect:** start with `[]` and `push` each matching item.

```javascript
const nums = [4, -2, 9];
let max = -Infinity;
const positives = [];
for (const n of nums) {
  if (n > max) {
    max = n;
  }
  if (n > 0) {
    positives.push(n);
  }
}
console.log(`Max: ${max}, positives: ${positives.join(", ")}`);
```

Why not start `max` at `0`? If every number is negative, `0` would wrongly win. Starting at the first item also works, but `-Infinity` lets every item go through the same check.

**The gotcha:** an empty array leaves `max` at `-Infinity`, and its average is `0 / 0`, which is `NaN`. Check `arr.length` first when the array might be empty.

example.code:
const scores = [72, 95, 58, 88, 64];

let highest = -Infinity;
let lowest = Infinity;
let sum = 0;
let failed = 0;
const passing = [];

for (const score of scores) {
  sum += score;
  if (score > highest) {
    highest = score;
  }
  if (score < lowest) {
    lowest = score;
  }
  if (score >= 60) {
    passing.push(score);
  } else {
    failed++;
  }
}

console.log(`Highest: ${highest}`);
console.log(`Lowest: ${lowest}`);
console.log(`Average: ${(sum / scores.length).toFixed(1)}`);
console.log(`Failed: ${failed}`);
console.log(`Passing scores: ${passing.join(", ")}`);

