practice.solution:
const rainfall = [12, 0, 7, 22, 3, 0, 15];

let wettest = -Infinity;
let driest = Infinity;
let total = 0;
let dryDays = 0;
const rainyDays = [];

for (const amount of rainfall) {
  total += amount;
  if (amount > wettest) {
    wettest = amount;
  }
  if (amount < driest) {
    driest = amount;
  }
  if (amount === 0) {
    dryDays++;
  } else {
    rainyDays.push(amount);
  }
}

console.log(`Wettest: ${wettest} mm`);
console.log(`Driest: ${driest} mm`);
console.log(`Average: ${(total / rainfall.length).toFixed(2)} mm`);
console.log(`Dry days: ${dryDays}`);
console.log(`Rainy days: ${rainyDays.join(", ")}`);
